  6287            if (nd == node) copy_node_opt_info(opt, &xo);
  6288            else            alt_merge_node_opt_info(opt, &xo, env);
  6289          }
  6290        } while ((r == 0) && IS_NOT_NULL(nd = NODE_CDR(nd)));
  6291      }
  6292      break;
  6293
  6294    case NODE_STRING:
  6295      {
  6296        StrNode* sn = STR_(node);
  6297        int slen = (int )(sn->end - sn->s);
  6298
  6299        concat_opt_exact_str(&opt->sb, sn->s, sn->end, enc);
  6300        if (slen > 0) {
  6301          add_char_opt_map(&opt->map, *(sn->s), enc);
