  6304      }
  6305      break;
  6306
  6307    case NODE_CCLASS:
  6308      {
  6309        int z;
  6310        CClassNode* cc = CCLASS_(node);
  6311
  6312        /* no need to check ignore case. (set in tune_tree()) */
  6313
  6314        if (IS_NOT_NULL(cc->mbuf) || IS_NCCLASS_NOT(cc)) {
  6315          OnigLen min = ONIGENC_MBC_MINLEN(enc);
  6316          OnigLen max = ONIGENC_MBC_MAXLEN_DIST(enc);
  6317
  6318          mml_set_min_max(&opt->len, min, max);
  6319        }
  6320        else {
  6321          for (i = 0; i < SINGLE_BYTE_SIZE; i++) {
  6322            z = BITSET_AT(cc->bs, i);
  6323            if ((z && ! IS_NCCLASS_NOT(cc)) || (! z && IS_NCCLASS_NOT(cc))) {
  6324              add_char_opt_map(&opt->map, (UChar )i, enc);
  6325            }
  6326          }
  6327          mml_set_min_max(&opt->len, 1, 1);
  6328        }
  6329      }
  6330      break;
  6331
  6332    case NODE_CTYPE:
  6333      {
  6334        int min, max;
  6335        int range;
  6336
  6337        max = ONIGENC_MBC_MAXLEN_DIST(enc);
  6338
  6339        if (max == 1) {
  6340          min = 1;
  6341
  6342          switch (CTYPE_(node)->ctype) {
  6343          case CTYPE_ANYCHAR:
  6344            break;
  6345
  6346          case ONIGENC_CTYPE_WORD:
  6347            range = CTYPE_(node)->ascii_mode != 0 ? 128 : SINGLE_BYTE_SIZE;
  6348            if (CTYPE_(node)->not != 0) {
  6349              for (i = 0; i < range; i++) {
  6350                if (! ONIGENC_IS_CODE_WORD(enc, i)) {
  6351                  add_char_opt_map(&opt->map, (UChar )i, enc);
  6352                }
  6353              }
  6354              for (i = range; i < SINGLE_BYTE_SIZE; i++) {
  6355                add_char_opt_map(&opt->map, (UChar )i, enc);
  6356              }
  6357            }
  6358            else {
  6359              for (i = 0; i < range; i++) {
  6360                if (ONIGENC_IS_CODE_WORD(enc, i)) {
  6361                  add_char_opt_map(&opt->map, (UChar )i, enc);
  6362                }
  6363              }
  6364            }
