  6377      case ANCR_BEGIN_BUF:
  6378      case ANCR_BEGIN_POSITION:
  6379      case ANCR_BEGIN_LINE:
  6380      case ANCR_END_BUF:
  6381      case ANCR_SEMI_END_BUF:
  6382      case ANCR_END_LINE:
  6383      case ANCR_PREC_READ_NOT:
  6384      case ANCR_LOOK_BEHIND:
