  6392            if (xo.sb.len > 0)
  6393              copy_opt_exact(&opt->spr, &xo.sb);
  6394            else if (xo.sm.len > 0)
  6395              copy_opt_exact(&opt->spr, &xo.sm);
  6396
  6397            opt->spr.reach_end = 0;
  6398
  6399            if (xo.map.value > 0)
  6400              copy_opt_map(&opt->map, &xo.map);
  6401          }
  6402        }
  6403        break;
  6404
  6405      case ANCR_LOOK_BEHIND_NOT:
  6406        break;
  6407      }
  6408      break;
  6409
  6410    case NODE_BACKREF:
  6411      if (! NODE_IS_CHECKER(node)) {
  6412        OnigLen min, max;
  6413
  6414        min = node_min_byte_len(node, env->scan_env);
  6415        max = node_max_byte_len(node, env->scan_env);
  6416        mml_set_min_max(&opt->len, min, max);
  6417      }
  6418      break;
  6419
  6420  #ifdef USE_CALL
  6421    case NODE_CALL:
  6422      if (NODE_IS_RECURSION(node))
  6423        mml_set_min_max(&opt->len, 0, INFINITE_LEN);
  6424      else {
  6425        r = optimize_nodes(NODE_BODY(node), opt, env);
  6426      }
  6427      break;
  6428  #endif
  6429
  6430    case NODE_QUANT:
  6431      {
  6432        OnigLen min, max;
  6433        QuantNode* qn = QUANT_(node);
  6434
  6435        r = optimize_nodes(NODE_BODY(node), &xo, env);
  6436        if (r != 0) break;
  6437
  6438        if (qn->lower > 0) {
  6439          copy_node_opt_info(opt, &xo);
  6440          if (xo.sb.len > 0) {
  6441            if (xo.sb.reach_end) {
  6442              for (i = 2; i <= qn->lower && ! is_full_opt_exact(&opt->sb); i++) {
  6443                int rc = concat_opt_exact(&opt->sb, &xo.sb, enc);
  6444                if (rc > 0) break;
  6445              }
  6446              if (i < qn->lower) opt->sb.reach_end = 0;
  6447            }
  6448          }
  6449
  6450          if (qn->lower != qn->upper) {
  6451            opt->sb.reach_end = 0;
  6452            opt->sm.reach_end = 0;
  6453          }
  6454          if (qn->lower > 1)
  6455            opt->sm.reach_end = 0;
  6456        }
  6457
  6458        if (IS_INFINITE_REPEAT(qn->upper)) {
  6459          if (env->mm.max == 0 &&
  6460              NODE_IS_ANYCHAR(NODE_BODY(node)) && qn->greedy != 0) {
  6461            if (NODE_IS_MULTILINE(NODE_QUANT_BODY(qn)))
  6462              add_opt_anc_info(&opt->anc, ANCR_ANYCHAR_INF_ML);
  6463            else
  6464              add_opt_anc_info(&opt->anc, ANCR_ANYCHAR_INF);
  6465          }
  6466
  6467          max = (xo.len.max > 0 ? INFINITE_LEN : 0);
  6468        }
  6469        else {
  6470          max = distance_multiply(xo.len.max, qn->upper);
  6471        }
  6472
  6473        min = distance_multiply(xo.len.min, qn->lower);
  6474        mml_set_min_max(&opt->len, min, max);
  6475      }
  6476      break;
  6477
  6478    case NODE_BAG:
  6479      {
  6480        BagNode* en = BAG_(node);
  6481
  6482        switch (en->type) {
  6483        case BAG_STOP_BACKTRACK:
  6484        case BAG_OPTION:
  6485          r = optimize_nodes(NODE_BODY(node), opt, env);
  6486          break;
  6487
  6488        case BAG_MEMORY:
  6489  #ifdef USE_CALL
  6490          en->opt_count++;
  6491          if (en->opt_count > MAX_NODE_OPT_INFO_REF_COUNT) {
  6492            OnigLen min, max;
  6493
  6494            min = 0;
  6495            max = INFINITE_LEN;
  6496            if (NODE_IS_FIXED_MIN(node)) min = en->min_len;
  6497            if (NODE_IS_FIXED_MAX(node)) max = en->max_len;
  6498            mml_set_min_max(&opt->len, min, max);
